#include "cuda_utils.cuh"
#include <vector>
#include <iostream>
__global__ void layernorm(const float* x,float* y,int rows,int cols,float eps){extern __shared__ float s[];float* ss=s;int row=blockIdx.x,t=threadIdx.x;float sum=0;for(int c=t;c<cols;c+=blockDim.x)sum+=x[row*cols+c];ss[t]=sum;__syncthreads();for(int st=blockDim.x/2;st;st>>=1){if(t<st)ss[t]+=ss[t+st];__syncthreads();}float mean=ss[0]/cols;float sq=0;for(int c=t;c<cols;c+=blockDim.x){float d=x[row*cols+c]-mean;sq+=d*d;}ss[t]=sq;__syncthreads();for(int st=blockDim.x/2;st;st>>=1){if(t<st)ss[t]+=ss[t+st];__syncthreads();}float inv=rsqrtf(ss[0]/cols+eps);for(int c=t;c<cols;c+=blockDim.x)y[row*cols+c]=(x[row*cols+c]-mean)*inv;}
int main(){int R=128,C=768,n=R*C;std::vector<float>x(n),y(n);for(int i=0;i<n;i++)x[i]=cosf(i*.02f)*3+0.2f;float *dx,*dy;CUDA_CHECK(cudaMalloc(&dx,n*4));CUDA_CHECK(cudaMalloc(&dy,n*4));CUDA_CHECK(cudaMemcpy(dx,x.data(),n*4,cudaMemcpyHostToDevice));layernorm<<<R,256,256*sizeof(float)>>>(dx,dy,R,C,1e-5f);check_kernel("layernorm");CUDA_CHECK(cudaMemcpy(y.data(),dy,n*4,cudaMemcpyDeviceToHost));for(int r=0;r<R;r++){double m=0,v=0;for(int c=0;c<C;c++)m+=y[r*C+c];m/=C;for(int c=0;c<C;c++){double d=y[r*C+c]-m;v+=d*d;}v/=C;if(std::fabs(m)>1e-4||std::fabs(v-1)>2e-3){std::cerr<<"FAIL\n";return 1;}}CUDA_CHECK(cudaFree(dx));CUDA_CHECK(cudaFree(dy));std::cout<<"PASS\n";}
